   "code": "ALLOWED = {\n    \"new\": {\"validated\", \"rejected_fp\"},\n    \"validated\": {\"prioritized\"},\n    \"prioritized\": {\"in_remediation\", \"risk_accepted\"},\n    \"in_remediation\": {\"retest\"},\n    \"retest\": {\"closed\", \"in_remediation\"},  # failed retest loops back\n    \"risk_accepted\": {\"prioritized\"},        # expiry re-opens review\n    \"closed\": set(), \"rejected_fp\": set(),\n}\n\nclass Finding:\n    def __init__(self, name):\n        self.name, self.state = name, \"new\"\n    def move(self, to):\n        if to not in ALLOWED[self.state]:\n            raise ValueError(f\"illegal: {self.state} -> {to}\")\n        print(f\"{self.name}: {self.state} -> {to}\")\n        self.state = to\n\nf = Finding(\"KEV RCE on file server\")\nf.move(\"validated\"); f.move(\"prioritized\")\nf.move(\"in_remediation\"); f.move(\"retest\"); f.move(\"closed\")\ntry:\n    Finding(\"shortcut\").move(\"closed\")\nexcept ValueError as e:\n    print(\"blocked:\", e)",
